mapper.select:
SELECT p.id AS plan_id, p.plan_no, p.order_id, p.order_detail_id, p.supplier_id, p.plan_quantity, p.plan_date, p.status, p.is_deleted, p.create_time, p.update_time, o.order_no, pm.EXTERNAL_PART_NO AS parts_no, pm.CHINESE_NAME AS parts_name, d.need_date AS requirement_date, COALESCE((SELECT SUM(a.ship_qty) FROM tb_srm_asn a WHERE a.order_detail_id = p.order_detail_id AND IFNULL(a.is_deleted, 0) = 0 AND a.status = 'SHIPPED'), 0) AS total_shipped, CASE WHEN COALESCE((SELECT SUM(a.ship_qty) FROM tb_srm_asn a WHERE a.order_detail_id = p.order_detail_id AND IFNULL(a.is_deleted, 0) = 0 AND a.status = 'SHIPPED'), 0) >= p.plan_quantity THEN 'SHIPPED' ELSE p.status END AS calculated_status FROM tb_delivery_plan p INNER JOIN tb_purchase_parts_order o ON p.order_id = o.id INNER JOIN tb_purchase_parts_order_detail d ON d.id = p.order_detail_id LEFT JOIN tb_parts_maint pm ON d.parts_number = pm.PARTS_NO AND pm.IS_DELETED = 0 WHERE 1=1
AND p.supplier_id = #{supplierId}
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND (
d.parts_number LIKE CONCAT('%', #{pn}, '%')
)
AND p.plan_date >= #{startDate}
AND p.plan_date <= #{endDate}
AND p.status = #{status}
ORDER BY p.plan_date ASC, p.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT p.order_id)
FROM tb_delivery_plan p
INNER JOIN tb_purchase_parts_order o ON p.order_id = o.id
INNER JOIN tb_purchase_parts_order_detail d ON d.id = p.order_detail_id
WHERE 1=1

    AND p.supplier_id = #{supplierId}


    AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND (

            d.parts_number LIKE CONCAT('%', #{pn}, '%')

    )


    AND p.plan_date >= #{startDate}


    AND p.plan_date <= #{endDate}


    AND p.status = #{status}

SELECT p.id AS plan_id, p.plan_no, p.order_id, p.order_detail_id, p.supplier_id, p.plan_quantity, p.plan_date, p.status, p.is_deleted, p.create_time, p.update_time, o.order_no, pm.EXTERNAL_PART_NO AS parts_no, pm.CHINESE_NAME AS parts_name, COALESCE((SELECT SUM(a.ship_qty) FROM tb_srm_asn a WHERE a.order_detail_id = p.order_detail_id AND IFNULL(a.is_deleted, 0) = 0 AND a.status = 'SHIPPED'), 0) AS shipped_qty, CASE WHEN COALESCE((SELECT SUM(a.ship_qty) FROM tb_srm_asn a WHERE a.order_detail_id = p.order_detail_id AND IFNULL(a.is_deleted, 0) = 0 AND a.status = 'SHIPPED'), 0) >= p.plan_quantity THEN 'SHIPPED' ELSE p.status END AS calculated_status FROM tb_delivery_plan p INNER JOIN tb_purchase_parts_order o ON p.order_id = o.id INNER JOIN tb_purchase_parts_order_detail d ON d.id = p.order_detail_id LEFT JOIN tb_parts_maint pm ON d.parts_number = pm.PARTS_NO AND pm.IS_DELETED = 0 WHERE p.plan_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 6 DAY) AND p.status != 'COMPLETED'
AND p.supplier_id = #{supplierId}
ORDER BY p.plan_date ASC, p.id DESC

SELECT COALESCE(MAX(CAST(RIGHT(plan_no, 4) AS UNSIGNED)), 0)
FROM tb_delivery_plan
WHERE supplier_id = #{supplierId}
